struct Fibonacci { a: Int, b: Int }

fn next(f: Fibonacci) -> Fibonacci {
    Fibonacci(b + f.a, f.b)
}

fn nth(n: Int) -> Int {
    let mut f = Fibonacci(1, 1)
    for _ in 0 < n {
        f = next(f)
    }
    f.a
}

